CREATE PROCEDURE sp_tbl_MLI_PLU_Attribute_Map AS /** ## Procedure Name       *[toast].[dbo].[sp_tbl_MLI_PLU_Attribute_Map]*   **Procedure Type**      *stored procedure*   **Author**              Wilson, Don < dwilson@newks.com >   **Version**             1   **Created**             20260227   ```      ### Output    *describe the fields of the result set   (if code is in this description, block the code with three backticks on a blank line above and below the code block.   After the first tripple backtick, place the name of the language the code is written in.   See the example of this in the Parameters section above.  Follow the second tuple with a blank line.*      ### Change History   **Change Date:**            *YYYYMMDD*   **Author:**                 *Last, First < email address >*   **Version**:                ##   **Change:**   *detail change here*      -------------------     **/ BEGIN     -- SET NOCOUNT ON added to prevent extra result sets from     -- interfering with SELECT statements.     SET NOCOUNT ON;      declare          -- If this is for a table build, then Tab, if not, then Proc 	    @RunType varchar(4) = 'Proc'          -- The time the procedure begins running 	   ,@StartTime datetime = getdate()        -- The database the procedure is running in 	   ,@DBName varchar(150) = DB_NAME()        -- The name of the procedure itself 	   ,@ProcName varchar(150) = OBJECT_NAME(@@PROCID)        -- Default the error information to no error 	   ,@ErrorNumber int = 0 	   ,@ErrorMessage varchar(250) = '' 	   ,@ErrorLine int = 0             BEGIN TRY                 -- if this is a table build, perform it as a transaction         if (@RunType = 'Tab') begin transaction;  		declare @Params varchar(2000) = (select '' as Params for json path)      	select distinct              convert(varchar(19),MultiLocationId) MultiLocationId, Item_GUID, Item_PLU as ToastPLU, 0 as AlohaPLU, Item_Name Toast_Item_Name, Item_Tags,          convert(varchar(100), '') AlohaItemName, convert(varchar(100), '') ConsolidatedCat, convert(varchar(100), '') Recipe, convert(varchar(100), '') GuestCountTag,          convert(varchar(100), '') EntreEquivTag, convert(varchar(100), '') LTOTag         into #Map         from toast.dbo.cfg_menu_items          update #map set             ConsolidatedCat = t.name         from #Map m         cross apply             openjson(Item_Tags)             with (name varchar(75) '$.name') as t         where (t.name like '* Cons%'                or t.name = 'Catering')          update #map set             GuestCountTag = try_cast(replace(t.name, 'Guest Count ', '') as decimal(3,1))         from #Map m         cross apply             openjson(Item_Tags)             with (name varchar(75) '$.name') as t         where (t.name like 'Guest%')          update #map set             Recipe = t.name         from #Map m         cross apply             openjson(Item_Tags)             with (name varchar(75) '$.name') as t         where t.name not like 'Guest%'         and t.name != 'Catering'         and t.name not like '* Cons%'         and t.name not like 'EE%'         and t.name not like '%lto%'          update #map set             EntreEquivTag = try_cast(replace(t.name, 'EE ', '') as decimal(3,1))         from #Map m         cross apply             openjson(Item_Tags)             with (name varchar(75) '$.name') as t         where t.name like 'EE%'          update #map set             LTOTag = t.name         from #Map m         cross apply             openjson(Item_Tags)             with (name varchar(75) '$.name') as t         where t.name like '%LTO%'          update #Map set             AlohaPLU = isnull(plu.AlohaPLU,0)         from #map m         join toast.dbo.cfg_map_PLU_Toast_to_Aloha plu         on m.MultiLocationId = convert(varchar(19),plu.MultiLocationID)          update #Map set             AlohaItemName = i.longname         from #Map m         join dev_aloha.dbo.item i         on m.AlohaPLU = i.ItemID          merge [toast].[dbo].[MLI_PLU_Attribute_Map] mpm         using #map m         on convert(varchar(19),mpm.MultiLocationID) = m.MultiLocationID         and mpm.Item_GUID = m.Item_GUID         and mpm.toastplu = m.toastplu         AND MPM.toast_item_name = m.toast_item_name         and mpm.AlohaPLU = m.alohaplu         when matched then update set             mpm.ToastPLU = m.ToastPLU,             mpm.AlohaPLU = m.AlohaPLU,             mpm.Toast_Item_Name = m.Toast_Item_Name,             mpm.AlohaItemName = m.AlohaItemName,             mpm.ConsolidatedCat = m.ConsolidatedCat,             mpm.Recipe = m.Recipe,             mpm.GuestCountTag = m.GuestCountTag,             mpm.EntreEquivTag = m.EntreEquivTag,             mpm.LTOTag = m.LTOTag         when not matched by target then              insert (MultiLocationId, Item_GUID, ToastPLU, AlohaPLU, Toast_Item_Name, AlohaItemName, ConsolidatedCat, Recipe, GuestCountTag, EntreEquivTag, LTOTag)             values (m.MultiLocationId, m.Item_GUID, m.ToastPLU, m.AlohaPLU, m.Toast_Item_Name, m.AlohaItemName, m.ConsolidatedCat, m.Recipe, m.GuestCountTag, m.EntreEquivTag, m.LTOTag);          drop table #Map                  -- If the table build has no error, then commit the transaction 		if (@RunType = 'Tab') commit transaction;                          -- Log the successful completion         exec Logging.dbo.Write_Procedure_Execution              @RunType = @RunType             ,@StartTime = @StartTime             ,@DBName = @DBName             ,@ProcName = @ProcName 			,@Params = @Params;                  END TRY     BEGIN CATCH         -- If there are errors and a transaction was started, roll it back         IF @@TRANCOUNT > 0         ROLLBACK TRANSACTION;                  -- Record the error details         set @ErrorNumber  = ERROR_NUMBER();         set @ErrorLine  = ERROR_LINE();         set @ErrorMessage  = ERROR_MESSAGE();                  -- Log the error         exec Logging.dbo.Write_Procedure_Execution              @RunType = @RunType             ,@StartTime = @StartTime             ,@DBName = @DBName             ,@ProcName = @ProcName             ,@ErrorNumber = @ErrorNumber             ,@ErrorMessage = @ErrorMessage             ,@ErrorLine = @ErrorLine 			,@Params = @Params;         THROW;     END CATCH END